type Shift = ContextShift;
type ShiftType = 'morning' | 'lunch' | 'evening' | 'double' | 'off';

const ZONES = [
    { id: 'main', name: 'planning.zones.main' },
    { id: 'terrace', name: 'planning.zones.terrace' },
    { id: 'vip', name: 'planning.zones.vip' },
