                onClose={() => setIsEditOpen(false)}
                title={activeUser?.name || "Nouveau Shift"}
                subtitle={`${format(selectedDay, "EEEE d MMMM", { locale: fr })}`}
            >
                <div className="space-y-8 py-6">
                    <div className="grid grid-cols-2 gap-4">
                        <TimePicker 
