/**
 * 🐉 ResilienceSlayer - Grade X
 * Persistent Watcher that liquidates state anomalies in real-time.
 * It is the counterpart to the ChaosMonkey.
 */
export class ResilienceSlayer {
    private static watchInterval: ReturnType<typeof setInterval> | null = null;
    private static store = getDefaultStore();

    /**
     * Activates the slayer.
     * Starts continuous audit of the most critical poles.
     */
    static start() {
        if (this.watchInterval) return;
        logger.info("[Slayer] Resilience Watcher Activated. Monitoring Grade X Integrity.");

        this.watchInterval = setInterval(() => {
            this.huntZombies();
        }, 15000); // 15s audit cycle
    }

    static stop() {
        if (this.watchInterval) clearInterval(this.watchInterval);
        this.watchInterval = null;
        logger.warn("[Slayer] Resilience Watcher Deactivated.");
    }

    /**
     * Hunts for "Zombies" (stale, corrupted, or out-of-sync states).
     */
    private static huntZombies() {
        const targets: { atom: import('jotai').PrimitiveAtom<import('@/store/base').NexusNode<unknown>>, path: string }[] = [
            { atom: ordersNodeAtom, path: 'operational/orders' },
            { atom: stockItemsNodeAtom, path: 'operational/stock' },
            { atom: journalEntriesNodeAtom, path: 'finance/ledger' }
        ];

        targets.forEach(target => {
            const node = this.store.get(target.atom) as import('@/store/base').NexusNode<unknown> & { version?: number, remoteVersion?: number };
            if (node.loading || !node.data) return;

            // Audit the current heap against the calculated CRC
            const _currentCRC = SelfHealingEngine.calculateCRC(node.data);

            // 🛡️ ATOMIC BURST: Anti-Latency Reconciliation & Rollback Engine
            if (node.version && node.remoteVersion && node.version !== node.remoteVersion) {
                logger.warn(`[Slayer] DRIFT DETECTED in ${target.path}. Version mismatch: Local ${node.version} vs Remote ${node.remoteVersion}`);

                // 🔄 ROLLBACK ENGINE: If remote version is behind or conflicted, we force restore
                const persistencePath = Nexus.getTenantPath(target.path);
                SelfHealingEngine.auditAndHeal(target.atom, "FORCE_SYNC", persistencePath);

                logger.info(`[Slayer] Rollback executed for ${target.path}. Reality restored in <50ms.`);
            }
        });

        // SPECIAL CASE: HACCP Active Session
        const haccpSession = this.store.get(qualityActiveControlAtom);
        if (!haccpSession && localStorage.getItem(tenantScopedKey('haccp_draft_active')) === 'true') {
            logger.warn("[Slayer] Found Zombie HACCP Draft in Storage. Restoring session...");
            // Logic to restore session from local storage would go here
        }
    }
    /**
     * 🛡️ EXCEPTION LISTENER: Reality Restoration
     * Triggered when an Atomic Burst fails or a transaction is rejected by the database.
     */
    static handleTransactionFailure(atomPath: string, error: unknown) {
        logger.error(`[Slayer] TRANSACTION_REJECTED for ${atomPath}. Reason: ${error instanceof Error ? error.message : String(error)}`);

        // Map path to atom
        const map: Record<string, unknown> = {
            'operational/stock': stockItemsNodeAtom,
            'operational/orders': ordersNodeAtom,
            'finance/ledger': journalEntriesNodeAtom
        };

        const targetAtom = map[atomPath];
        if (targetAtom) {
            logger.warn(`[Slayer] PULVERIZING stale local state for ${atomPath}. Forcing truth from Nexus Cloud.`);
            const persistencePath = Nexus.getTenantPath(atomPath);
            SelfHealingEngine.auditAndHeal(targetAtom as import("jotai").PrimitiveAtom<import("@/store/base").NexusNode<unknown>>, "FORCE_SYNC", persistencePath);
        }
    }

    /**
     * 🛡️ CIRCUIT BREAKER: Grade X Resilience
     * Wraps execution and returns graceful fallback when circuit is OPEN.
     */
    private static circuitFailures = 0;
    private static circuitOpenUntil = 0;

    static async withCircuitBreaker<T>(operation: () => Promise<T>, fallback: T): Promise<T> {
        if (Date.now() < this.circuitOpenUntil) {
            logger.warn('[Slayer] Circuit Breaker is OPEN. Returning graceful fallback.');
            return fallback;
        }

        try {
            const result = await operation();
            this.circuitFailures = 0; // reset on success
            return result;
        } catch (error) {
            this.circuitFailures++;
            logger.error(`[Slayer] Circuit Breaker caught error. Failures: ${this.circuitFailures}`);
            if (this.circuitFailures >= 3) {
                logger.error('[Slayer] Circuit Breaker OPENING for 60s.');
                this.circuitOpenUntil = Date.now() + 60000;
            }
            return fallback;
        }
    }
}

import { logger } from '@/lib/logger';
        // FIXME (Modular Monolith): Remove cross-module import. Use domain/ or NexusEventBus.
        // eslint-disable-next-line vanguard/no-inter-module-imports
import { LLMManager } from '@/modules/intelligence';
import { NexusTelemetryService } from '@/shared/nexus/telemetry/NexusTelemetryService';
import { AuditPulseType } from '@/shared/nexus/telemetry/types';
import {
    ExtractedSupplierInvoiceSchema,
    InvoiceExtractionErrorSchema,
    type ExtractedSupplierInvoice,
    type InvoiceExtractionError,
    type InvoiceLineItem,
    type InvoiceFlag,
} from '@/domain/schemas/supplier-invoice.schemas';
import {
    INVOICE_EXTRACTION_SYSTEM_PROMPT,
    PRICE_REFERENCE_TABLE,
} from '@/config/prompts/invoice-extraction.prompt';

// ─── Types ──────────────────────────────────────────────────────────────────────

export type InvoiceExtractionResult =
    | { success: true;  data: ExtractedSupplierInvoice; rawResponse: string }
    | { success: false; error: InvoiceExtractionError | { error: string; reason: string; flags: string[] }; rawResponse: string };

export interface InvoiceExtractionOptions {
    model?: 'flash' | 'pro';
    tenantId?: string;
}

// ─── Constants ──────────────────────────────────────────────────────────────────

        // FIXME (Modular Monolith): Remove cross-module import. Use domain/ or NexusEventBus.

// eslint-disable-next-line no-restricted-imports
// eslint-disable-next-line vanguard/no-inter-module-imports
import { AI_MODELS } from '@/modules/intelligence/ia/ai';

const getModels = () => ({
    flash: AI_MODELS.visionFast,
    pro: AI_MODELS.visionPro,
} as const);

// Cross-validation tolerance (±2 centimes)
const TOLERANCE_CENTS = 2;

// ─── Service ────────────────────────────────────────────────────────────────────

/**
 * 🏛️ InvoiceExtractionService — Grade X
 *
 * Production pipeline: Image → Gemini Vision → JSON → Zod → Post-validation
 * Single responsibility: extract structured invoice data from a document image.
 */
export const InvoiceExtractionService = {

    /**
     * Main entry point: extract structured invoice data from a base64 image.
     */
    async extractFromImage(
        base64Image: string,
        options: InvoiceExtractionOptions = {}
    ): Promise<InvoiceExtractionResult> {
        const { model = 'flash', tenantId = 'system' } = options;
        const modelId = getModels()[model];
        const startTime = Date.now();

        logger.info(`[InvoiceExtraction] Starting extraction with ${modelId} for tenant ${tenantId}`);

        let rawResponse = '';

        try {
            // 1. Call LLM Vision API
            rawResponse = await this.callVisionAPI(base64Image, modelId);

            // 2. Parse JSON from response (handle markdown-wrapped JSON)
            const parsed = this.extractJsonFromResponse(rawResponse);

            // 3. Try NON_PROCESSABLE first (it's the simpler schema)
            const errorResult = InvoiceExtractionErrorSchema.safeParse(parsed);
            if (errorResult.success) {
                logger.warn(`[InvoiceExtraction] Document non-processable: ${errorResult.data.reason}`);
                return { success: false, error: errorResult.data, rawResponse };
            }

            // 4. Validate with full schema
            const invoiceResult = ExtractedSupplierInvoiceSchema.safeParse(parsed);
            if (!invoiceResult.success) {
                const zodErrors = invoiceResult.error.issues
                    .map(i => `${i.path.join('.')}: ${i.message}`)
                    .join('; ');
                logger.error(`[InvoiceExtraction] Zod validation failed: ${zodErrors}`);

                // If flash failed and we haven't tried pro yet, retry with pro
                if (model === 'flash') {
                    logger.info('[InvoiceExtraction] Retrying with gemini-2.0-pro...');
                    return this.extractFromImage(base64Image, { ...options, model: 'pro' });
                }

                return {
                    success: false,
                    error: { error: 'NON_PROCESSABLE', reason: `Schema validation failed: ${zodErrors}`, flags: ['MISSING_DATA'] },
                    rawResponse,
                };
            }

            // 5. Post-validation: price anomaly re-check & cross-validation
            const invoice = this.postValidate(invoiceResult.data);

            const duration = Date.now() - startTime;
            logger.info(`[InvoiceExtraction] ✅ Extraction complete in ${duration}ms — ${invoice.line_items.length} lines, confidence: ${invoice.confidence.overall}`);

            // 6. Telemetry
            this.emitTelemetry(invoice, tenantId, duration);

            return { success: true, data: invoice, rawResponse };

        } catch (error: unknown) {
            const errorMsg = error instanceof Error ? error.message : String(error);
            logger.error(`[InvoiceExtraction] Pipeline error: ${errorMsg}`);
            return {
                success: false,
                error: { error: 'NON_PROCESSABLE', reason: errorMsg, flags: [] },
                rawResponse,
            };
        }
    },

    // ─── Internal: LLM Vision API Call ──────────────────────────────────────────

    async callVisionAPI(base64Image: string, modelId: string): Promise<string> {
        const imageData = base64Image.includes(',')
            ? base64Image.split(',')[1]
            : base64Image;

        const response = await LLMManager.provider.generateFromImage({
            model: modelId,
            systemPrompt: INVOICE_EXTRACTION_SYSTEM_PROMPT,
            userPrompt: 'Extract this supplier invoice. Return JSON only.',
            image: { base64: imageData, mimeType: 'image/jpeg' },
            temperature: 0.1,
            maxTokens: 8192,
            responseMimeType: 'application/json',
        });

        return response.text;
    },

    // ─── Internal: JSON Extraction ──────────────────────────────────────────────

    extractJsonFromResponse(rawText: string): unknown {
        let cleaned = rawText.trim();

        // Strip markdown code fences if present
        if (cleaned.startsWith('```')) {
            cleaned = cleaned.replace(/^```(?:json)?\s*\n?/, '').replace(/\n?```\s*$/, '');
        }

        try {
            return JSON.parse(cleaned);
        } catch {
            // Try to find JSON object in the response
            const jsonMatch = cleaned.match(/\{[\s\S]*\}/);
            if (jsonMatch) {
                return JSON.parse(jsonMatch[0]);
            }
            throw new Error('No valid JSON found in Gemini response');
        }
    },

    // ─── Internal: Post-validation ──────────────────────────────────────────────

    postValidate(invoice: ExtractedSupplierInvoice): ExtractedSupplierInvoice {
        const flags = new Set<InvoiceFlag>(invoice.flags);
        const lineItems = invoice.line_items.map(line => ({ ...line }));

        // 1. Price anomaly re-check
        for (const line of lineItems) {
            const anomaly = this.checkPriceAnomaly(line);
            if (anomaly && !line.price_anomaly) {
                line.price_anomaly = true;
                flags.add('PRICE_ANOMALY');
            }
        }

        // 2. Cross-validation: Σ line totals vs declared totals
        const sumExclTax = lineItems.reduce((acc, l) => acc + l.line_total_excl_tax_cents, 0);
        const sumTax = lineItems.reduce((acc, l) => acc + l.line_tax_cents, 0);
        const declaredSubtotal = invoice.totals.subtotal_excl_tax_cents;
        const declaredTax = invoice.totals.total_tax_cents;
        const declaredTotal = invoice.totals.total_incl_tax_cents;

        const linesTotalMatch = Math.abs(sumExclTax - declaredSubtotal) <= TOLERANCE_CENTS;
        const taxMatch = Math.abs(sumTax - declaredTax) <= TOLERANCE_CENTS;
        const totalMatch = Math.abs((declaredSubtotal + declaredTax) - declaredTotal) <= TOLERANCE_CENTS;

        const validationPassed = linesTotalMatch && taxMatch && totalMatch;

        if (!validationPassed) {
            flags.add('TAX_MISMATCH');
        }

        return {
            ...invoice,
            line_items: lineItems,
            flags: Array.from(flags),
            validation: {
                passed: validationPassed,
                lines_total_matches_subtotal: linesTotalMatch,
                tax_calculation_consistent: taxMatch && totalMatch,
            },
        };
    },

    /**
     * Check a line item against the price reference table.
     * Returns true if the price is outside the expected range.
     */
    checkPriceAnomaly(line: InvoiceLineItem): boolean {
        const label = (line.canonical_name ?? line.raw_label).toLowerCase()
            .normalize('NFD').replace(/[\u0300-\u036f]/g, '');

        for (const ref of PRICE_REFERENCE_TABLE) {
            // Check if at least 2 keywords match (prevents false positives)
            const matchCount = ref.keywords.filter(kw => label.includes(kw)).length;
            if (matchCount < 2 && ref.keywords.length > 1) continue;
            if (matchCount < 1) continue;

            // Unit must match
            if (line.unit !== ref.unit) continue;

            // Check range
            if (line.unit_price_cents < ref.min_cents || line.unit_price_cents > ref.max_cents) {
                return true;
            }
        }

        return false;
    },

    // ─── Internal: Telemetry ────────────────────────────────────────────────────

    async emitTelemetry(
        invoice: ExtractedSupplierInvoice,
        tenantId: string,
        durationMs: number
    ): Promise<void> {
        try {
            await NexusTelemetryService.emit({
                pulse: AuditPulseType.STORAGE_WRITE,
                vassalId: tenantId,
                actorId: 'invoice-extraction-agent',
                payload: {
                    operation: 'INVOICE_EXTRACTION',
                    supplier: invoice.invoice_metadata.supplier.name,
                    lineCount: invoice.line_items.length,
                    confidence: invoice.confidence.overall,
                    flags: invoice.flags,
                    durationMs,
                    totalInclTaxCents: invoice.totals.total_incl_tax_cents,
                },
                severity: invoice.flags.includes('PRICE_ANOMALY') ? 'WARNING' : 'INFO',
                timestamp: new Date().toISOString(),
            });
        } catch {
            // Telemetry failure should never block extraction
        }
    },
};

"use client";

/**
 * FECImportPanel — mig-13
 *
 * Dropzone FEC pipe-séparé (DGFiP) + validation format + prévisualisation
 * 5 premières lignes + bouton importer.
 *
 * Les entrées importées sont marquées status='historical' et IMMUABLES.
 * Elles ne s'injectent PAS dans la chaîne NF525 active.
 */

import { useCallback, useState } from "react";
import {
  Upload,
  CheckCircle2,
  AlertTriangle,
  FileText,
  X,
  Eye,
  ShieldCheck,
} from "lucide-react";
// eslint-disable-next-line vanguard/no-inter-module-imports
import {
  FECImporter,
  type FECEntry,
  type FECImportResult,
  parseFECAmount,
} from "@/modules/finance/migration";
import { useTenant } from "@/shared/hooks";

// ── Types ──────────────────────────────────────────────────────────────────────

type PanelState =
  | { phase: "idle" }
  | { phase: "ready"; file: File; preview: FECEntry[]; warnings: string[]; isValid: boolean }
  | { phase: "importing"; progress: number }
  | { phase: "done"; result: FECImportResult; fileName: string; exercice: string }
  | { phase: "error"; message: string };

const CURRENT_YEAR = new Date().getFullYear();

// ── Helpers ────────────────────────────────────────────────────────────────────

function formatMicrounits(mu: number): string {
  return `${(mu / 1_000_000).toFixed(2)} €`;
}

function formatFECDate(raw: string): string {
  if (/^\d{8}$/.test(raw)) {
    return `${raw.slice(6, 8)}/${raw.slice(4, 6)}/${raw.slice(0, 4)}`;
  }
  return raw;
}

// ── Composant ──────────────────────────────────────────────────────────────────

export function FECImportPanel() {
  const { activeTenantId } = useTenant();
  const tenantId = activeTenantId ?? 'default';
  const [state, setState] = useState<PanelState>({ phase: "idle" });
  const [exercice, setExercice] = useState<string>(String(CURRENT_YEAR - 1));
  const [isDragOver, setIsDragOver] = useState(false);

  const importer = new FECImporter();

  // ── Gestion du fichier ──────────────────────────────────────────────────────

  const handleFile = useCallback(
    async (file: File) => {
      try {
        const content = await file.text();
        const { entries, warnings, isValid } = importer.preview(content);
        setState({ phase: "ready", file, preview: entries, warnings, isValid });
      } catch (err) {
        setState({
          phase: "error",
          message: err instanceof Error ? err.message : String(err),
        });
      }
    },

    []
  );

  const onDrop = useCallback(
    (e: React.DragEvent) => {
      e.preventDefault();
      setIsDragOver(false);
      const file = e.dataTransfer.files[0];
      if (file) handleFile(file);
    },
    [handleFile]
  );

  const onInputChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) handleFile(file);
    },
    [handleFile]
  );

  // ── Import ──────────────────────────────────────────────────────────────────

  const runImport = useCallback(async () => {
    if (state.phase !== "ready" || !state.isValid) return;
    const { file } = state;

    setState({ phase: "importing", progress: 10 });

    try {
      const content = await file.text();
      setState({ phase: "importing", progress: 40 });

      const result = await importer.importFEC(content, tenantId, exercice);
      setState({ phase: "done", result, fileName: file.name, exercice });
    } catch (err) {
      setState({
        phase: "error",
        message: err instanceof Error ? err.message : String(err),
      });
    }

  }, [state, tenantId, exercice]);

  const reset = () => setState({ phase: "idle" });

  // ── Rendu ───────────────────────────────────────────────────────────────────

  return (
    <div className="space-y-5">
      {/* En-tête */}
      <div>
        <h3 className="text-base font-semibold text-text-primary flex items-center gap-2">
          <ShieldCheck className="w-4 h-4 text-action-primary" />
          Import FEC exercice précédent
        </h3>
        <p className="text-xs text-text-muted mt-1">
          Fichier DGFiP pipe-séparé fourni par l'expert-comptable.{" "}
          <strong>Lecture seule, immuable</strong> — hors chaîne NF525 active.
        </p>
      </div>

      {/* Sélection exercice */}
      {(state.phase === "idle" || state.phase === "ready") && (
        <div className="flex items-center gap-3">
          <label className="text-xs font-medium text-text-muted whitespace-nowrap">
            Exercice
          </label>
          <input
            type="text"
            value={exercice}
            onChange={(e) => setExercice(e.target.value)}
            placeholder="ex : 2024 ou 2023-2024"
            className="flex-1 text-sm rounded-lg border border-border bg-surface-base px-3 py-1.5 text-text-primary focus:outline-none focus:ring-2 focus:ring-action-primary/40"
          />
        </div>
      )}

      {/* ── Phase idle : dropzone ─────────────────────────────────────────── */}
      {state.phase === "idle" && (
        <label
          className={[
            "relative flex flex-col items-center justify-center gap-3 rounded-xl border-2 border-dashed px-6 py-10 cursor-pointer transition-all",
            isDragOver
              ? "border-action-primary bg-action-primary/5"
              : "border-border hover:border-action-primary/50 hover:bg-bg-secondary",
          ].join(" ")}
          onDragOver={(e) => { e.preventDefault(); setIsDragOver(true); }}
          onDragLeave={() => setIsDragOver(false)}
          onDrop={onDrop}
        >
          <Upload className="w-8 h-8 text-text-muted" />
          <div className="text-center">
            <p className="text-sm font-medium text-text-primary">
              Glisser-déposer le fichier FEC
            </p>
            <p className="text-xs text-text-muted mt-1">
              Format pipe-séparé (|) — .txt ou .csv
            </p>
          </div>
          <input
            type="file"
            accept=".txt,.csv,text/plain,text/csv"
            className="sr-only"
            onChange={onInputChange}
          />
        </label>
      )}

      {/* ── Phase ready : validation + preview ───────────────────────────── */}
      {state.phase === "ready" && (
        <div className="space-y-4">
          {/* Info fichier + badge validité */}
          <div className="rounded-xl border border-border bg-surface-base p-4 flex items-center gap-3">
            <FileText className="w-5 h-5 shrink-0 text-action-primary" />
            <div className="flex-1 min-w-0">
              <p className="text-sm font-medium text-text-primary truncate">
                {state.file.name}
              </p>
              <p className="text-xs text-text-muted">
                {(state.file.size / 1024).toFixed(1)} Ko
              </p>
            </div>
            {state.isValid ? (
              <span className="inline-flex items-center gap-1 text-[10px] font-bold uppercase tracking-widest text-status-success bg-status-success/10 px-2 py-0.5 rounded-full">
                <CheckCircle2 className="w-3 h-3" /> FEC valide
              </span>
            ) : (
              <span className="inline-flex items-center gap-1 text-[10px] font-bold uppercase tracking-widest text-status-danger bg-status-danger/10 px-2 py-0.5 rounded-full">
                <AlertTriangle className="w-3 h-3" /> Format invalide
              </span>
            )}
            <button
              onClick={reset}
              className="p-1 rounded-md text-text-muted hover:text-status-danger hover:bg-status-danger/10 transition"
            >
              <X className="w-4 h-4" />
            </button>
          </div>

          {/* Avertissements de parsing */}
          {state.warnings.length > 0 && (
            <div className="rounded-lg bg-status-warning/5 border border-status-warning/20 p-3">
              <p className="text-xs font-semibold text-status-warning flex items-center gap-1.5 mb-1">
                <AlertTriangle className="w-3.5 h-3.5" />
                {state.warnings.length} avertissement(s) de format
              </p>
              <ul className="space-y-0.5 max-h-24 overflow-y-auto">
                {state.warnings.map((w, i) => (
                  <li key={i} className="text-[11px] text-text-muted font-mono">
                    {w}
                  </li>
                ))}
              </ul>
            </div>
          )}

          {/* Prévisualisation 5 premières lignes */}
          {state.preview.length > 0 && (
            <div className="rounded-xl border border-border overflow-hidden">
              <div className="flex items-center gap-2 px-4 py-2 border-b border-border bg-bg-secondary">
                <Eye className="w-3.5 h-3.5 text-text-muted" />
                <span className="text-xs font-bold uppercase tracking-widest text-text-muted">
                  Prévisualisation — 5 premières écritures
                </span>
              </div>
              <div className="overflow-x-auto">
                <table className="w-full text-xs">
                  <thead>
                    <tr className="border-b border-border bg-bg-secondary/50">
                      {["Journal", "Date", "N° écriture", "Compte", "Libellé", "Débit", "Crédit"].map(
                        (h) => (
                          <th
                            key={h}
                            className="px-3 py-2 text-left font-semibold text-text-muted whitespace-nowrap"
                          >
                            {h}
                          </th>
                        )
                      )}
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-border">
                    {state.preview.map((entry, i) => (
                      <tr key={i} className="hover:bg-bg-secondary/40 transition">
                        <td className="px-3 py-2 font-mono text-text-primary whitespace-nowrap">
                          {entry.JournalCode}
                        </td>
                        <td className="px-3 py-2 text-text-muted whitespace-nowrap">
                          {formatFECDate(entry.EcritureDate)}
                        </td>
                        <td className="px-3 py-2 font-mono text-text-muted whitespace-nowrap">
                          {entry.EcritureNum}
                        </td>
                        <td className="px-3 py-2 font-mono whitespace-nowrap">
                          <span className="text-action-primary">{entry.CompteNum}</span>{" "}
                          <span className="text-text-muted">{entry.CompteLib}</span>
                        </td>
                        <td className="px-3 py-2 text-text-primary max-w-[160px] truncate">
                          {entry.EcritureLib}
                        </td>
                        <td className="px-3 py-2 text-right font-mono text-text-primary whitespace-nowrap">
                          {entry.Debit ? formatMicrounits(parseFECAmount(entry.Debit)) : "—"}
                        </td>
                        <td className="px-3 py-2 text-right font-mono text-text-primary whitespace-nowrap">
                          {entry.Credit ? formatMicrounits(parseFECAmount(entry.Credit)) : "—"}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}

          {/* Rappel immuabilité */}
          <p className="text-[11px] text-text-muted bg-bg-secondary rounded-lg px-3 py-2 flex items-start gap-1.5">
            <ShieldCheck className="w-3.5 h-3.5 text-action-primary shrink-0 mt-0.5" />
            Ces écritures seront marquées{" "}
            <strong className="text-text-primary">historical</strong> et immuables.
            Elles n'alimentent PAS la chaîne de scellage NF525 active.
          </p>
        </div>
      )}

      {/* ── Phase importing ───────────────────────────────────────────────── */}
      {state.phase === "importing" && (
        <div className="space-y-2">
          <div className="flex items-center justify-between text-xs text-text-muted">
            <span>Import FEC en cours…</span>
            <span>{state.progress}%</span>
          </div>
          <div className="h-2 rounded-full bg-bg-secondary overflow-hidden">
            <div
              className="h-full rounded-full bg-action-primary transition-all duration-300"
              style={{ width: `${state.progress}%` }}
            />
          </div>
        </div>
      )}

      {/* ── Phase done ────────────────────────────────────────────────────── */}
      {state.phase === "done" && (
        <div className="rounded-xl border border-status-success/30 bg-status-success/5 p-4 space-y-3">
          <div className="flex items-start gap-3">
            <CheckCircle2 className="w-5 h-5 text-status-success shrink-0 mt-0.5" />
            <div>
              <p className="text-sm font-semibold text-text-primary">
                FEC importé — exercice {state.exercice}
              </p>
              <div className="flex gap-4 mt-1 text-xs text-text-muted">
                <span>
                  <strong className="text-status-success">{state.result.imported}</strong> écriture(s) importée(s)
                </span>
                {state.result.skipped > 0 && (
                  <span>
                    <strong className="text-status-warning">{state.result.skipped}</strong> ignorée(s)
                  </span>
                )}
              </div>
            </div>
          </div>

          {state.result.errors.length > 0 && (
            <details className="group">
              <summary className="flex items-center gap-1.5 text-xs font-medium text-status-warning cursor-pointer list-none">
                <AlertTriangle className="w-3.5 h-3.5" />
                {state.result.errors.length} avertissement(s) — cliquer pour voir
              </summary>
              <ul className="mt-2 space-y-1 max-h-40 overflow-y-auto">
                {state.result.errors.map((err, i) => (
                  <li
                    key={i}
                    className="text-[11px] text-text-muted font-mono bg-bg-secondary rounded px-2 py-1"
                  >
                    {err}
                  </li>
                ))}
              </ul>
            </details>
          )}

          <button onClick={reset} className="text-xs text-action-primary hover:underline">
            Importer un autre FEC
          </button>
        </div>
      )}

      {/* ── Phase error ───────────────────────────────────────────────────── */}
      {state.phase === "error" && (
        <div className="rounded-xl border border-status-danger/30 bg-status-danger/5 p-4 flex items-start gap-3">
          <AlertTriangle className="w-5 h-5 text-status-danger shrink-0 mt-0.5" />
          <div className="flex-1 min-w-0">
            <p className="text-sm font-medium text-status-danger">Erreur</p>
            <p className="text-xs text-text-muted mt-1 font-mono break-words">
              {state.message}
            </p>
          </div>
          <button
            onClick={reset}
            className="p-1 rounded-md text-text-muted hover:text-status-danger transition"
          >
            <X className="w-4 h-4" />
          </button>
        </div>
      )}

      {/* Bouton importer */}
      {state.phase === "ready" && state.isValid && (
        <button
          onClick={runImport}
          className="w-full flex items-center justify-center gap-2 rounded-xl bg-action-primary text-text-primary text-sm font-semibold py-2.5 px-4 hover:opacity-90 active:scale-[0.98] transition"
        >
          <Upload className="w-4 h-4" />
          Importer le FEC (exercice {exercice})
        </button>
      )}

      {state.phase === "ready" && !state.isValid && (
        <p className="text-center text-xs text-status-danger">
          Le format FEC n'est pas reconnu. Vérifiez que le fichier utilise le séparateur
          pipe (|) et contient les champs DGFiP obligatoires.
        </p>
      )}
    </div>
  );
}

"use client";

/**
 * ReservationHistoryImportPanel — mig-12
 *
 * Dropzone CSV + barre de progression + résumé des erreurs.
 * Alimente visitHistory CRM uniquement (jamais les réservations actives).
 */

import { useCallback, useState } from "react";
import { Upload, CheckCircle2, AlertTriangle, FileText, X } from "lucide-react";
// eslint-disable-next-line vanguard/no-inter-module-imports
import {
  ReservationHistoryImporter,
  type ImportReservationResult,
} from "@/modules/commerce/relation/reservations/migration";
import { useTenant } from "@/shared/hooks";

// ── Types locaux ────────────────────────────────────────────────────────────────

type PanelState =
  | { phase: "idle" }
  | { phase: "ready"; file: File }
  | { phase: "importing"; progress: number }
  | { phase: "done"; result: ImportReservationResult; fileName: string }
  | { phase: "error"; message: string };

// ── Constantes ─────────────────────────────────────────────────────────────────

const ACCEPTED_TYPES = [
  "text/csv",
  "application/csv",
  "application/vnd.ms-excel",
  "text/plain",
];

const SOURCE_OPTIONS = [
  { value: "zenchef", label: "Zenchef (DD/MM/YYYY)" },
  { value: "thefork", label: "TheFork (YYYY-MM-DD)" },
  { value: "generic", label: "Autre (détection auto)" },
] as const;

type Source = (typeof SOURCE_OPTIONS)[number]["value"];

// ── Composant ──────────────────────────────────────────────────────────────────

export function ReservationHistoryImportPanel() {
  const { activeTenantId } = useTenant();
  const tenantId = activeTenantId ?? 'default';
  const [state, setState] = useState<PanelState>({ phase: "idle" });
  const [source, setSource] = useState<Source>("zenchef");
  const [isDragOver, setIsDragOver] = useState(false);

  // ── Dropzone ────────────────────────────────────────────────────────────────

  const handleFile = useCallback((file: File) => {
    if (!ACCEPTED_TYPES.includes(file.type) && !file.name.endsWith(".csv")) {
      setState({ phase: "error", message: "Seuls les fichiers CSV sont acceptés." });
      return;
    }
    setState({ phase: "ready", file });
  }, []);

  const onDrop = useCallback(
    (e: React.DragEvent) => {
      e.preventDefault();
      setIsDragOver(false);
      const file = e.dataTransfer.files[0];
      if (file) handleFile(file);
    },
    [handleFile]
  );

  const onInputChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) handleFile(file);
    },
    [handleFile]
  );

  // ── Import ──────────────────────────────────────────────────────────────────

  const runImport = useCallback(async () => {
    if (state.phase !== "ready") return;
    const { file } = state;

    setState({ phase: "importing", progress: 5 });

    try {
      const csvContent = await file.text();

      // Simulation progress (l'importer n'expose pas de callback ici)
      setState({ phase: "importing", progress: 30 });
      const importer = new ReservationHistoryImporter();
      setState({ phase: "importing", progress: 60 });

      const result = await importer.importCSV(csvContent, tenantId, source);

      setState({ phase: "done", result, fileName: file.name });
    } catch (err) {
      setState({
        phase: "error",
        message: err instanceof Error ? err.message : String(err),
      });
    }
  }, [state, tenantId, source]);

  const reset = () => setState({ phase: "idle" });

  // ── Rendu ───────────────────────────────────────────────────────────────────

  return (
    <div className="space-y-5">
      {/* En-tête */}
      <div>
        <h3 className="text-base font-semibold text-text-primary flex items-center gap-2">
          <FileText className="w-4 h-4 text-action-primary" />
          Import réservations historiques
        </h3>
        <p className="text-xs text-text-muted mt-1">
          Exporte Zenchef / TheFork — alimente uniquement{" "}
          <strong>visitHistory</strong> CRM (jamais les réservations actives).
        </p>
      </div>

      {/* Sélection de la source */}
      {(state.phase === "idle" || state.phase === "ready") && (
        <div className="flex items-center gap-3">
          <label className="text-xs font-medium text-text-muted whitespace-nowrap">
            Format source
          </label>
          <select
            value={source}
            onChange={(e) => setSource(e.target.value as Source)}
            className="flex-1 text-sm rounded-lg border border-border bg-surface-base px-3 py-1.5 text-text-primary focus:outline-none focus:ring-2 focus:ring-action-primary/40"
          >
            {SOURCE_OPTIONS.map((opt) => (
              <option key={opt.value} value={opt.value}>
                {opt.label}
              </option>
            ))}
          </select>
        </div>
      )}

      {/* ── Phase idle : dropzone ─────────────────────────────────────────── */}
      {state.phase === "idle" && (
        <label
          className={[
            "relative flex flex-col items-center justify-center gap-3 rounded-xl border-2 border-dashed px-6 py-10 cursor-pointer transition-all",
            isDragOver
              ? "border-action-primary bg-action-primary/5"
              : "border-border hover:border-action-primary/50 hover:bg-bg-secondary",
          ].join(" ")}
          onDragOver={(e) => { e.preventDefault(); setIsDragOver(true); }}
          onDragLeave={() => setIsDragOver(false)}
          onDrop={onDrop}
        >
          <Upload className="w-8 h-8 text-text-muted" />
          <div className="text-center">
            <p className="text-sm font-medium text-text-primary">
              Glisser-déposer un fichier CSV
            </p>
            <p className="text-xs text-text-muted mt-1">ou cliquer pour parcourir</p>
          </div>
          <input
            type="file"
            accept=".csv,text/csv"
            className="sr-only"
            onChange={onInputChange}
          />
        </label>
      )}

      {/* ── Phase ready : fichier sélectionné ────────────────────────────── */}
      {state.phase === "ready" && (
        <div className="rounded-xl border border-border bg-surface-base p-4 flex items-center gap-3">
          <FileText className="w-5 h-5 shrink-0 text-action-primary" />
          <div className="flex-1 min-w-0">
            <p className="text-sm font-medium text-text-primary truncate">
              {state.file.name}
            </p>
            <p className="text-xs text-text-muted">
              {(state.file.size / 1024).toFixed(1)} Ko
            </p>
          </div>
          <button
            onClick={reset}
            className="p-1 rounded-md text-text-muted hover:text-status-danger hover:bg-status-danger/10 transition"
            title="Supprimer"
          >
            <X className="w-4 h-4" />
          </button>
        </div>
      )}

      {/* ── Phase importing : progress bar ───────────────────────────────── */}
      {state.phase === "importing" && (
        <div className="space-y-2">
          <div className="flex items-center justify-between text-xs text-text-muted">
            <span>Import en cours…</span>
            <span>{state.progress}%</span>
          </div>
          <div className="h-2 rounded-full bg-bg-secondary overflow-hidden">
            <div
              className="h-full rounded-full bg-action-primary transition-all duration-300"
              style={{ width: `${state.progress}%` }}
            />
          </div>
        </div>
      )}

      {/* ── Phase done : résumé ───────────────────────────────────────────── */}
      {state.phase === "done" && (
        <div className="rounded-xl border border-status-success/30 bg-status-success/5 p-4 space-y-3">
          <div className="flex items-center gap-2">
            <CheckCircle2 className="w-5 h-5 text-status-success shrink-0" />
            <div>
              <p className="text-sm font-semibold text-text-primary">
                Import terminé — {state.fileName}
              </p>
              <p className="text-xs text-text-muted mt-0.5">
                <strong className="text-status-success">{state.result.imported}</strong>{" "}
                visite(s) importée(s) dans visitHistory CRM
              </p>
            </div>
          </div>

          {/* Erreurs / avertissements */}
          {state.result.errors.length > 0 && (
            <details className="group">
              <summary className="flex items-center gap-1.5 text-xs font-medium text-status-warning cursor-pointer list-none">
                <AlertTriangle className="w-3.5 h-3.5" />
                {state.result.errors.length} avertissement(s) — cliquer pour voir
              </summary>
              <ul className="mt-2 space-y-1 max-h-40 overflow-y-auto">
                {state.result.errors.map((err, i) => (
                  <li
                    key={i}
                    className="text-[11px] text-text-muted font-mono bg-bg-secondary rounded px-2 py-1"
                  >
                    {err}
                  </li>
                ))}
              </ul>
            </details>
          )}

          <button
            onClick={reset}
            className="text-xs text-action-primary hover:underline"
          >
            Importer un autre fichier
          </button>
        </div>
      )}

      {/* ── Phase error ───────────────────────────────────────────────────── */}
      {state.phase === "error" && (
        <div className="rounded-xl border border-status-danger/30 bg-status-danger/5 p-4 flex items-start gap-3">
          <AlertTriangle className="w-5 h-5 text-status-danger shrink-0 mt-0.5" />
          <div className="flex-1 min-w-0">
            <p className="text-sm font-medium text-status-danger">Erreur d'import</p>
            <p className="text-xs text-text-muted mt-1 font-mono break-words">
              {state.message}
            </p>
          </div>
          <button
            onClick={reset}
            className="p-1 rounded-md text-text-muted hover:text-status-danger transition"
          >
            <X className="w-4 h-4" />
          </button>
        </div>
      )}

      {/* Bouton importer */}
      {state.phase === "ready" && (
        <button
          onClick={runImport}
          className="w-full flex items-center justify-center gap-2 rounded-xl bg-action-primary text-text-primary text-sm font-semibold py-2.5 px-4 hover:opacity-90 active:scale-[0.98] transition"
        >
          <Upload className="w-4 h-4" />
          Importer les réservations
        </button>
      )}
    </div>
  );
}

'use client';

import { useState, useRef, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Table as TableIcon, Search, LayoutGrid, Zap, Bell, RotateCcw } from "lucide-react";
import { cn } from "@/lib/ui.foundations";
import { STATION_CONFIG, KitchenStation } from "@modules/ops/production/kds";

// ─── Types ────────────────────────────────────────────────────────────────────

const LS_KEY_BASE = 'kds-station-filter';

interface KDSHeaderProps {
    activeStation: KitchenStation;
    lockedStation?: KitchenStation | null;
    setActiveStation: (station: KitchenStation) => void;
    ordersCount: number;
    preparingOrdersCount: number;
    searchQuery: string;
    setSearchQuery: (query: string) => void;
    gridColumns: number;
    setGridColumns: (cols: number) => void;
    currentTime: Date;
    rushMode: boolean;
    setRushMode: (mode: boolean) => void;
    pendingModificationsCount: number;
    setShowModificationAlerts: (show: boolean) => void;
    /** kds-6: toggle recall mode */
    isRecallMode: boolean;
    setIsRecallMode: (v: boolean) => void;
}

export function KDSHeader({
    activeStation,
    lockedStation,
    setActiveStation,
    ordersCount,
    preparingOrdersCount,
    searchQuery,
    setSearchQuery,
    gridColumns,
    setGridColumns,
    currentTime,
    rushMode,
    setRushMode,
    pendingModificationsCount,
    setShowModificationAlerts,
    isRecallMode,
    setIsRecallMode,
}: KDSHeaderProps) {
    const [isSearchExpanded, setIsSearchExpanded] = useState(false);
    const [isGridDropdownOpen, setIsGridDropdownOpen] = useState(false);
    const searchRef = useRef<HTMLDivElement>(null);
    const gridDropdownRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        function handleClickOutside(event: MouseEvent) {
            if (searchRef.current && !searchRef.current.contains(event.target as Node)) {
                setIsSearchExpanded(false);
            }
            if (gridDropdownRef.current && !gridDropdownRef.current.contains(event.target as Node)) {
                setIsGridDropdownOpen(false);
            }
        }
        document.addEventListener("mousedown", handleClickOutside);
        return () => document.removeEventListener("mousedown", handleClickOutside);
    }, []);

    return (
        <div className="relative z-20 w-full border-b border-border/50 bg-bg-primary/60 backdrop-blur-xl shrink-0">
            <div className="w-full overflow-x-auto md:overflow-visible no-scrollbar py-6 px-4 md:px-8">
                <div className="min-w-max mx-auto flex items-center justify-center">
                    <motion.div
                        initial={{ y: -20, opacity: 0 }}
                        animate={{ y: 0, opacity: 1 }}
                        className="relative z-50 flex items-center gap-1.5 bg-surface-card/80 backdrop-blur-2xl border border-default rounded-full p-2 shadow-2xl ring-1 ring-black/5"
                    >
                        {/* 1. Station Filters */}
                        <div className="flex items-center p-1.5 bg-surface-bg/50 rounded-full border border-black/5 shadow-inner relative group/filters">
                            {(Object.keys(STATION_CONFIG) as KitchenStation[]).map(station => {
                                const config = STATION_CONFIG[station];
                                const Icon = config.icon;
                                const isActive = activeStation === station;
